/**
 * Photo storage: local disk (development, tests, a regular server) or Supabase Storage
 * (serverless hosting, where the local disk is ephemeral). Chosen automatically from the config.
 * Objects are private: they are only ever served by the API after an access check.
 */
import fs from 'node:fs/promises'
import path from 'node:path'
import { config } from '../config'

export interface PhotoStorage {
  readonly kind: 'local' | 'supabase'
  put(key: string, body: Buffer, contentType: string): Promise<void>
  get(key: string): Promise<Buffer | null>
}

// Keys are generated by the API (UUID + extension); basename() is a belt-and-braces guard.
const safeKey = (key: string) => path.basename(key)

const local: PhotoStorage = {
  kind: 'local',
  async put(key, body) {
    await fs.mkdir(config.uploadDir, { recursive: true })
    await fs.writeFile(path.join(config.uploadDir, safeKey(key)), body, { mode: 0o600 })
  },
  async get(key) {
    try {
      return await fs.readFile(path.join(config.uploadDir, safeKey(key)))
    } catch {
      return null
    }
  },
}

function supabase(): PhotoStorage {
  const { url, serviceRoleKey, bucket } = config.supabase
  const object = (key: string) => `${url}/storage/v1/object/${encodeURIComponent(bucket)}/${encodeURIComponent(safeKey(key))}`
  // Legacy service_role keys are JWTs (sent as apikey + Bearer); the newer sb_secret_… keys are not JWTs
  // and only go in the apikey header.
  const auth: Record<string, string> = serviceRoleKey.startsWith('eyJ')
    ? { Authorization: `Bearer ${serviceRoleKey}`, apikey: serviceRoleKey }
    : { apikey: serviceRoleKey }
  return {
    kind: 'supabase',
    async put(key, body, contentType) {
      const res = await fetch(object(key), {
        method: 'POST',
        headers: { ...auth, 'Content-Type': contentType, 'x-upsert': 'false', 'Cache-Control': 'max-age=31536000' },
        body: new Uint8Array(body),
        signal: AbortSignal.timeout(20_000),
      })
      if (!res.ok) throw new Error(`Supabase Storage ${res.status}: ${(await res.text().catch(() => '')).slice(0, 200)}`)
    },
    async get(key) {
      const res = await fetch(object(key), { headers: auth, signal: AbortSignal.timeout(20_000) })
      if (res.status === 404 || res.status === 400) return null
      if (!res.ok) throw new Error(`Supabase Storage ${res.status}`)
      return Buffer.from(await res.arrayBuffer())
    },
  }
}

export function photoStorage(): PhotoStorage {
  return config.supabase.url && config.supabase.serviceRoleKey ? supabase() : local
}
